  it("does not mutate the input", () => {
    const input = sample();
    clear(input);
    expect(input).toEqual(sample());
  });

  it("returns an empty array for an empty list and keeps all when none are done", () => {
    expect(clear([])).toEqual([]);
    const open = [{ id: 1, title: "x", done: false }];
